import type { ReactNode, SVGProps } from "react";

import type { ItemCategoryId } from "./itemCategoryCatalog";

type IconProps = SVGProps<SVGSVGElement>;

export type CategoryIconPixelSize = 16 | 24;

type CategoryIconProps = IconProps & {
  pixelSize: CategoryIconPixelSize;
};

function categorySvg(
  pixelSize: CategoryIconPixelSize,
  viewBoxSize: 16 | 24,
  props: IconProps,
  children: ReactNode,
) {
  return (
    <svg
      width={pixelSize}
      height={pixelSize}
      viewBox={`0 0 ${viewBoxSize} ${viewBoxSize}`}
      fill="none"
      aria-hidden
      {...props}
    >
      {children}
    </svg>
  );
}

