export function ItemCategoryIcon({
  categoryId,
  pixelSize,
  className,
}: {
  categoryId: ItemCategoryId;
  pixelSize: CategoryIconPixelSize;
  className?: string;
}) {
  const Icon = iconsByCategoryId[categoryId];
  return <Icon pixelSize={pixelSize} className={className} />;
}

